import React from 'react';
import { useQuery } from '@tanstack/react-query';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Truck, DollarSign, Package, MapPin, Clock, TrendingUp } from 'lucide-react';
import dispatchService from '../../services/dispatchService';
import StatusBadge from '../../components/datadisplay/StatusBadge';

const DispatchOverview = () => {
    const navigate = useNavigate();
    const { data, isLoading } = useQuery({
        queryKey: ['dispatch-dashboard'],
        queryFn: dispatchService.getDashboard
    });

    return (
        <div className="space-y-6">
            <div>
                <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Dispatch Dashboard</h1>
                <p className="text-gray-500 mt-1">Overview of your delivery operations</p>
            </div>

            {/* Stats Grid */}
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="bg-white dark:bg-gray-800 rounded-xl p-4 shadow-sm border"
                >
                    <div className="flex items-center gap-2 mb-2">
                        <Truck className="h-5 w-5 text-teal-600" />
                        <span className="text-sm text-gray-500">Active</span>
                    </div>
                    <p className="text-2xl font-bold">{data?.activeDeliveries || 0}</p>
                </motion.div>

                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.1 }}
                    className="bg-white dark:bg-gray-800 rounded-xl p-4 shadow-sm border"
                >
                    <div className="flex items-center gap-2 mb-2">
                        <DollarSign className="h-5 w-5 text-emerald-600" />
                        <span className="text-sm text-gray-500">Earnings</span>
                    </div>
                    <p className="text-2xl font-bold">${(data?.totalEarnings || 0).toLocaleString()}</p>
                </motion.div>

                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.2 }}
                    className="bg-white dark:bg-gray-800 rounded-xl p-4 shadow-sm border"
                >
                    <div className="flex items-center gap-2 mb-2">
                        <Clock className="h-5 w-5 text-amber-600" />
                        <span className="text-sm text-gray-500">Pending</span>
                    </div>
                    <p className="text-2xl font-bold">${(data?.pendingEarnings || 0).toLocaleString()}</p>
                </motion.div>

                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.3 }}
                    className="bg-white dark:bg-gray-800 rounded-xl p-4 shadow-sm border"
                >
                    <div className="flex items-center gap-2 mb-2">
                        <TrendingUp className="h-5 w-5 text-purple-600" />
                        <span className="text-sm text-gray-500">Paid</span>
                    </div>
                    <p className="text-2xl font-bold">${(data?.paidEarnings || 0).toLocaleString()}</p>
                </motion.div>
            </div>

            {/* Recent Assignments */}
            <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.2 }}
                className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border"
            >
                <div className="p-4 border-b border-gray-200 dark:border-gray-700">
                    <h3 className="font-semibold text-gray-900 dark:text-white">Recent Assignments</h3>
                </div>

                {isLoading ? (
                    <div className="p-8 text-center">
                        <div className="w-8 h-8 border-2 border-teal-500 border-t-transparent rounded-full animate-spin mx-auto" />
                    </div>
                ) : (
                    <div className="divide-y divide-gray-200 dark:divide-gray-700">
                        {data?.recentAssignments?.map(assignment => (
                            <div
                                key={assignment.id}
                                onClick={() => navigate(`/dispatch/dashboard/details/${assignment.id}`)}
                                className="p-4 hover:bg-gray-50 dark:hover:bg-gray-750 transition-colors cursor-pointer"
                            >
                                <div className="flex items-center justify-between">
                                    <div className="flex items-center gap-3">
                                        <div className="h-10 w-10 rounded-lg bg-gray-100 dark:bg-gray-700 flex items-center justify-center overflow-hidden">
                                            {assignment.productImage ? (
                                                <img src={assignment.productImage} alt={assignment.productName} className="h-full w-full object-cover" />
                                            ) : (
                                                <Package className="h-5 w-5 text-gray-400" />
                                            )}
                                        </div>
                                        <div>
                                            <p className="font-medium text-gray-900 dark:text-white">{assignment.productName}</p>
                                            <div className="flex items-center gap-1 text-sm text-gray-500">
                                                <MapPin className="h-3 w-3" />
                                                {assignment.customerCity}, {assignment.customerState}
                                            </div>
                                        </div>
                                    </div>
                                    <div className="text-right">
                                        <StatusBadge status={assignment.status} size="sm" />
                                        {assignment.deliveryFee > 0 && (
                                            <p className="text-sm font-medium mt-1">${assignment.deliveryFee.toFixed(2)}</p>
                                        )}
                                    </div>
                                </div>
                            </div>
                        ))}
                        {(!data?.recentAssignments || data.recentAssignments.length === 0) && (
                            <p className="p-8 text-center text-gray-500">No deliveries assigned yet</p>
                        )}
                    </div>
                )}
            </motion.div>
        </div>
    );
};

export default DispatchOverview;
